CONSTANTS = 'const BASE_GUARDIAN_RARITY = {\n  minotaur: "Légendaire",\n  harpy: "Épique",\n  mummy: "Rare",\n  gargoyle: "Épique",\n  dragon: "Divin",\n  toad: "Rare",\n  imp: "Commun",\n  cerberus: "Mythique",\n  golem: "Mythique",\n  spectre: "Légendaire",\n  knight: "Épique",\n  abyss: "Mythique",\n  anubis: "Légendaire",\n};\n\nconst BASE_GUARDIAN_DROP_WEIGHT = {\n  minotaur: 25,\n  harpy: 45,\n  mummy: 70,\n  gargoyle: 45,\n  dragon: 5,\n  toad: 70,\n  imp: 100,\n  cerberus: 12,\n  golem: 12,\n  spectre: 25,\n  knight: 45,\n  abyss: 14,\n  anubis: 22,\n};\n\nconst BASE_ITEM_RARITY = {\n  blade: "Rare",\n  plate: "Épique",\n  amulet: "Rare",\n  orb: "Légendaire",\n  potion: "Commun",\n  fragment: "Épique",\n};\n\nconst DEFAULT_SECURE_CHESTS = {\n  chest: {\n    monsterChance: 35,\n    rarities: {\n      Commun: 60,\n      Rare: 30,\n      "Épique": 9,\n      "Légendaire": 1,\n      Mythique: 0,\n      Divin: 0,\n    },\n    equipment: { potion: 55, blade: 25, amulet: 20 },\n    goldMin: 180,\n    goldMax: 400,\n    mana: 180,\n  },\n  starterRareChest: {\n    monsterChance: 100,\n    rarities: {\n      Commun: 100,\n      Rare: 0,\n      "Épique": 0,\n      "Légendaire": 0,\n      Mythique: 0,\n      Divin: 0,\n    },\n    equipment: { potion: 1 },\n    goldMin: 400,\n    goldMax: 800,\n    mana: 360,\n  },\n  rareChest: {\n    monsterChance: 60,\n    rarities: {\n      Commun: 15,\n      Rare: 50,\n      "Épique": 28,\n      "Légendaire": 6,\n      Mythique: 1,\n      Divin: 0,\n    },\n    equipment: {\n      potion: 20,\n      blade: 35,\n      amulet: 30,\n      plate: 15,\n    },\n    goldMin: 400,\n    goldMax: 800,\n    mana: 360,\n  },\n  epicChest: {\n    monsterChance: 80,\n    rarities: {\n      Commun: 0,\n      Rare: 15,\n      "Épique": 58,\n      "Légendaire": 22,\n      Mythique: 4,\n      Divin: 1,\n    },\n    equipment: {\n      blade: 15,\n      amulet: 20,\n      plate: 45,\n      orb: 20,\n    },\n    goldMin: 700,\n    goldMax: 1300,\n    mana: 600,\n  },\n  legendChest: {\n    monsterChance: 100,\n    rarities: {\n      Commun: 0,\n      Rare: 0,\n      "Épique": 25,\n      "Légendaire": 55,\n      Mythique: 17,\n      Divin: 3,\n    },\n    equipment: { plate: 40, orb: 60 },\n    goldMin: 1200,\n    goldMax: 2200,\n    mana: 1000,\n  },\n};\n\nconst DEFAULT_GUARDIAN_EVOLUTION_VPS = {\n  maxLevel0: 50,\n  maxLevel1: 100,\n  maxLevel2: 150,\n  maxLevel3: 200,\n};\n\n'
